ST.xhtml:
BranchPassThenFail();
FirstFailureCoherent();
TenThousandInvocations();
ZeroAssertions();
ThreeAssertions();
LaterFailureExecuted := _first >= 2;

TEST('BranchPassThenFail');
IF NOT IS_TEST_FINISHED('BranchPassThenFail') THEN
	_branch := _branch + 1;
	IF _branch = 1 THEN
		AssertTrue(Condition := TRUE, Message := 'A');
	ELSE
		AssertFalse(Condition := TRUE, Message := 'B');
		TEST_FINISHED();
	END_IF
END_IF

TEST('FirstFailureCoherent');
IF NOT IS_TEST_FINISHED('FirstFailureCoherent') THEN
	_first := _first + 1;
	IF _first = 1 THEN
		AssertTrue(Condition := FALSE, Message := 'first-A');
	ELSE
		AssertFalse(Condition := TRUE, Message := 'later-B');
		TEST_FINISHED();
	END_IF
END_IF

TEST('TenThousandInvocations');
IF NOT IS_TEST_FINISHED('TenThousandInvocations') THEN
	_long := _long + 1;
	_good := _long < 10000;
	AssertTrue(Condition := _good, Message := 'last-invocation');
	IF _long >= 10000 THEN TEST_FINISHED(); END_IF
END_IF

TEST('ZeroAssertions');
IF NOT IS_TEST_FINISHED('ZeroAssertions') THEN
	TEST_FINISHED();
END_IF

TEST('ThreeAssertions');
IF NOT IS_TEST_FINISHED('ThreeAssertions') THEN
	AssertTrue(Condition := TRUE, Message := 'one');
	AssertTrue(Condition := TRUE, Message := 'two');
	AssertTrue(Condition := TRUE, Message := 'three');
	TEST_FINISHED();
END_IF

