FUNCTION_BLOCK FB_QualificationMultiscan EXTENDS FB_TestSuite
VAR_OUTPUT
	LaterFailureExecuted : BOOL;
END_VAR
VAR
	_branch : UDINT;
	_first : UDINT;
	_long : UDINT;
	_good : BOOL;
END_VAR

PROGRAM PRG_Qualification
VAR_OUTPUT
	Done : BOOL;
	OraclePass : BOOL;
	FailedCheck : UDINT;
	SnapshotBytes : UDINT;
END_VAR
VAR
	_suite1 : FB_QualificationMultiscan;
	_snapshot : REFERENCE TO ST_CoUnitRunSnapshot;

END_VAR
